import { camera, createAuraApp, lights, material, primitives, scene } from "@aura3d/engine";

// The robot is built from primitives, since no real robot.glb has been admitted via `aura3d assets`.
async function main(): Promise<void> {
  const metal = material.pbr({ color: "#c9d1de", roughness: 0.4 });
  const app = createAuraApp("#app", {
  scene: scene({ background: "#1b2230" })
    .add(lights.directional({ position: [4, 6, 3], intensity: 2.5 }))
    .add(primitives.plane({ name: "floor", size: [14, 1, 14], material: material.pbr({ color: "#7b8494", roughness: 0.8 }), receiveShadow: true }))
    .add(primitives.box({ name: "robot-body", size: [0.8, 1, 0.5], position: [0, 1, 0], material: metal }))
    .add(primitives.box({ name: "robot-head", size: [0.5, 0.4, 0.4], position: [0, 1.75, 0], material: metal }))
    .add(primitives.box({ name: "robot-leg-left", size: [0.25, 0.5, 0.25], position: [-0.2, 0.25, 0], material: metal }))
    .add(primitives.box({ name: "robot-leg-right", size: [0.25, 0.5, 0.25], position: [0.2, 0.25, 0], material: metal }))
    .camera(camera.orbit({ target: [0, 1, 0], distance: 6, fov: 40 }))
});
  await app.ready();
}
void main();
